package vn.hansol.workarea.watch;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.os.*;
import android.view.View;
import android.widget.*;
import com.google.android.gms.wearable.*;
import org.json.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.*;
import vn.hansol.workarea.shared.Secrets;

public class WatchActivity extends Activity {
 private LinearLayout content;private final Handler handler=new Handler();private final ExecutorService io=Executors.newCachedThreadPool();private volatile int generation=0;private volatile String connection="Chưa kết nối server";private volatile JSONObject challenge;private String selected="";private volatile int phoneNodes=-1;
 private final BroadcastReceiver receiver=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){runOnUiThread(()->{selected="";render();});}};
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.rgb(8,18,28));content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(25),dp(34),dp(25),dp(38));scroll.addView(content);setContentView(scroll);try{String claim=Secrets.get(this,"pair_claim");if(claim!=null){JSONObject c=new JSONObject(claim);if(c.optLong("expires")>System.currentTimeMillis())challenge=c;}}catch(Exception ignored){}render();}
 @Override protected void onStart(){super.onStart();WatchApp.foreground=true;if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,new IntentFilter(WatchAlerts.CHANGED),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,new IntentFilter(WatchAlerts.CHANGED));render();int ticket=++generation;io.execute(()->loop(ticket));handler.post(tick);Wearable.getDataClient(this).getDataItems().addOnSuccessListener(buffer->{try{for(DataItem item:buffer)WatchDataService.consume(this,item);}finally{buffer.release();}});}
 @Override protected void onStop(){WatchApp.foreground=false;generation++;handler.removeCallbacks(tick);unregisterReceiver(receiver);super.onStop();}
 @Override protected void onDestroy(){io.shutdown();super.onDestroy();}
 private final Runnable tick=new Runnable(){@Override public void run(){if(!WatchApp.foreground)return;Wearable.getNodeClient(WatchActivity.this).getConnectedNodes().addOnSuccessListener(nodes->{phoneNodes=nodes.size();render();}).addOnFailureListener(error->{phoneNodes=-1;render();});handler.postDelayed(this,10000);}};
 private void loop(int ticket){while(WatchApp.foreground&&ticket==generation){try{
  JSONObject pair=WatchStore.pair(this);if(pair!=null){WatchSync.pull(this,true);connection="Server: đã kết nối";}
  else if(challenge!=null&&challenge.optLong("expires")>System.currentTimeMillis()){JSONObject c=challenge,result=WatchRemote.call(this,"/api/watch/pair/redeem",new JSONObject().put("pair_id",c.getString("pair_id")).put("claim",c.getString("claim")),false);if(!result.optBoolean("pending")){WatchStore.pair(this,result);Secrets.clear(this,"pair_claim");challenge=null;connection="Đã ghép đôi";Wearable.getDataClient(this).getDataItems().addOnSuccessListener(buffer->{try{for(DataItem item:buffer)WatchDataService.consume(this,item);}finally{buffer.release();}});}Thread.sleep(2500);}
  else Thread.sleep(2000);
 }catch(Exception error){connection="Chưa kết nối server · vẫn nhận Data Layer";try{Thread.sleep(4000);}catch(InterruptedException ignored){}}runOnUiThread(this::render);}}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size,int color){TextView view=new TextView(this);view.setText(value);view.setTextSize(size);view.setTextColor(color);view.setPadding(0,dp(4),0,dp(4));view.setTextIsSelectable(true);content.addView(view,new LinearLayout.LayoutParams(-1,-2));return view;}
 private void button(String label,View.OnClickListener action){Button button=new Button(this);button.setText(label);button.setTextSize(13);button.setAllCaps(false);button.setOnClickListener(action);content.addView(button,new LinearLayout.LayoutParams(-1,-2));}
 private String time(String iso){try{return DateTimeFormatter.ofPattern("HH:mm:ss dd/MM").withZone(ZoneId.systemDefault()).format(Instant.parse(iso));}catch(Exception e){return iso;}}
 private int color(String status){return "PASS".equals(status)?Color.rgb(110,234,160):"NG".equals(status)?Color.rgb(255,115,128):"NOT_FOUND".equals(status)?Color.rgb(255,205,107):Color.rgb(143,208,255);}
 private void startPair(){io.execute(()->{try{JSONObject c=WatchRemote.call(this,"/api/watch/pair/start",new JSONObject(),false);Secrets.put(this,"pair_claim",c.toString());challenge=c;connection="Nhập mã này trên điện thoại";}catch(Exception e){connection="Cần Internet để ghép đôi lần đầu";}runOnUiThread(this::render);});}
 private void render(){if(isFinishing())return;content.removeAllViews();text("WORK AREA",16,Color.rgb(139,225,211));JSONObject pair=WatchStore.pair(this);if(pair==null){text("Ghép đôi đồng hồ",21,Color.WHITE);JSONObject c=challenge;if(c!=null&&c.optLong("expires")>System.currentTimeMillis()){String code=c.optString("code");text(code.length()==8?code.substring(0,4)+" "+code.substring(4):code,30,Color.rgb(130,235,205));text("Trên điện thoại: Tải xuống & Sao lưu → Galaxy Watch. Mã có hiệu lực 5 phút.",14,Color.LTGRAY);}button("Lấy mã ghép đôi mới",v->startPair());text(connection,13,Color.LTGRAY);permissions();return;}
  text(pair.optString("owner"),14,Color.LTGRAY);text(phoneNodes>0?"Điện thoại: kết nối Wear OS":"Điện thoại: chưa thấy kết nối",12,phoneNodes>0?Color.rgb(120,225,180):Color.LTGRAY);text(connection,12,Color.LTGRAY);boolean push=getSharedPreferences("watch-state",0).getBoolean("push_configured",false);if(!push||!WatchApp.pushReady())text("Web: push nền chưa cấu hình. APK điện thoại dùng Data Layer.",11,Color.rgb(255,207,124));
  try(WatchStore store=new WatchStore(this)){JSONArray history=store.history();text("Lịch sử quét · Không phải tồn kho hiện tại",12,Color.LTGRAY);if(store.state("enabled",1)==0)text("Gửi đồng hồ đang tắt",17,Color.rgb(255,207,124));if(history.length()==0)text("Đang chờ kết quả quét",20,Color.WHITE);else{JSONObject event=history.getJSONObject(0);if(!selected.isEmpty())for(int i=0;i<history.length();i++)if(history.getJSONObject(i).getString("event_id").equals(selected))event=history.getJSONObject(i);detail(event);text("20 kết quả gần nhất · "+history.length(),15,Color.WHITE);for(int i=0;i<history.length();i++){JSONObject row=history.getJSONObject(i);String id=row.getString("event_id"),code=row.getJSONArray("codes").getJSONObject(0).optString("normalized");button(time(row.getString("scanned_at"))+"\n"+row.optString("status_label")+" · "+code,v->{selected=id;render();});}}}catch(Exception error){text("Chưa đọc được lịch sử",16,Color.LTGRAY);}
  permissions();button("Hủy ghép đôi trên đồng hồ",v->new AlertDialog.Builder(this).setMessage("Xóa ghép đôi và lịch sử trên đồng hồ?").setPositiveButton("Xóa",(dialog,which)->{Secrets.clear(this,"pair");Secrets.clear(this,"pair_claim");getSharedPreferences("watch-state",0).edit().clear().apply();try(WatchStore store=new WatchStore(this)){store.getWritableDatabase().delete("events",null,null);store.getWritableDatabase().delete("state",null,null);}((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancelAll();challenge=null;render();}).setNegativeButton("Giữ lại",null).show());
 }
 private void detail(JSONObject event)throws Exception{text(event.optString("module")+" · "+event.optString("status_label"),23,color(event.optString("status")));text(time(event.getString("scanned_at")),13,Color.LTGRAY);if(event.optBoolean("provisional"))text("Kết quả từ dữ liệu offline · tạm tính",12,Color.rgb(255,207,124));JSONArray codes=event.getJSONArray("codes");for(int i=0;i<codes.length();i++){JSONObject code=codes.getJSONObject(i);text(code.optString("label"),12,Color.LTGRAY);text(code.getString("normalized"),20,Color.WHITE);if(!code.getString("raw").equals(code.getString("normalized")))text("Mã gốc: "+code.getString("raw"),14,Color.LTGRAY);}if(!event.optString("title").isEmpty())text(event.getString("title"),18,Color.WHITE);JSONArray fields=event.getJSONArray("fields");for(int i=0;i<fields.length();i++){JSONObject field=fields.getJSONObject(i);text(field.getString("label"),12,Color.LTGRAY);text(field.getString("value"),16,Color.WHITE);}}
 private void permissions(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)button("Cho phép thông báo",v->requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},91));}
}
